    fn check(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        batch: ls::Value,
    ) -> ls::Result<()> {
        let t = lawspec_schema::schema()?.validate_with_context(
            t,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let txid = lawspec_schema::schema()?.validate_with_context(
            txid,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let batch = lawspec_schema::schema()?.validate_with_context(
            batch,
            &ls::TypeRef::named(
                "List",
                vec![ls::TypeRef::named(
                    "lawtwin.kafka.model::type::Record",
                    vec![],
                )],
            ),
            64,
            ctx,
        )?;
        let with_cluster = ls::called(
            "lawtwin.kafka::connectCluster",
            connect_cluster(ctx, vec![ls::Value::Unit]),
        )?;
        ls::bracket(
            ctx,
            |ctx| {
                let installing = vec![("lawtwin.kafka::ability::Broker".to_string(), {
                    let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker> =
                        std::sync::Arc::new(adapter::BrokerHandler::new(
                            <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                lawspec_schema::schema()?.native_value_with_context(
                                    with_cluster.clone(),
                                    &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                    64,
                                    ctx,
                                )?,
                            )?,
                        ));
                    ls::installed_native::<adapter::BrokerHandler, _>(handler)
                })];
                ctx.install_handlers(installing);
                check_body(
                    ctx,
                    t.clone(),
                    txid.clone(),
                    batch.clone(),
                    with_cluster.clone(),
                )?;
                Ok(())
            },
            |ctx| {
                Ok(ls::called(
                    "lawtwin.kafka::disconnectCluster",
                    disconnect_cluster(ctx, vec![with_cluster.clone()]),
                )?)
            },
        )?;
        Ok(())
    }

    fn valid(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        batch: ls::Value,
    ) -> ls::Result<bool> {
        let condition = ls::called(
            "lawtwin.kafka::lawtwinKafkaModelValidTopicName",
            lawspec_definitions::lawtwin_kafka_model_valid_topic_name(ctx, vec![t.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::binary("!=", "Text", txid.clone(), ls::Value::Text("".to_owned()))?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::called(
            "lawtwin.kafka::smallBatch",
            lawspec_definitions::small_batch(ctx, vec![batch.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        Ok(true)
    }

    #[test]
    fn boundaries() -> ls::Result<()> {
        ls::with_stack(|| {
            ls::finite_cases(
                &ls::FiniteCover::Branches(vec![
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("o".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text(" ".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_6(ctx)?)]),
                                ls::FiniteCover::Copies(1),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("t".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("Hello, World!".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_7(ctx)?)]),
                                ls::FiniteCover::Copies(1),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| {
                            Ok(ls::Value::Text("7oIEcKM".to_owned()))
                        }]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("λ日本語😀".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_8(ctx)?)]),
                                ls::FiniteCover::Copies(1),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| {
                            Ok(ls::Value::Text("ucnH_8".to_owned()))
                        }]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("a\n\t\"\\$\0z".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_9(ctx)?)]),
                                ls::FiniteCover::Copies(1),
                            )]),
                        )]),
                    ),
                ]),
                |case_index, factories| {
                    let ctx = &mut ls::Context::testing();
                    let values = factories
                        .iter()
                        .map(|factory| factory.materialize(ctx))
                        .collect::<ls::Result<Vec<_>>>()?;
                    check(ctx, values[0].clone(), values[1].clone(), values[2].clone()).map_err(
                        |error| format!("boundary {}: values={values:?}: {error}", case_index + 1),
                    )
                },
            )?;
            Ok(())
        })
    }

