// Broker: |a new epoch fences the older producer| [cluster] — ../src/contract.lawspec:142
// Initialising a transactional id again bumps its epoch. Every request
// stamped with the older epoch is refused from then on, so a zombie
// instance can no longer write.
// References: KIP-98
// for all (t :: Text) (txid :: Text) (batch :: List (lawtwin.kafka.model::type::Record)) => created
// t 1 implies let tp = let _lawspecRecordField0 = t in let _lawspecRecordField1 = 0 in
// lawtwin.kafka.model::type::TopicPartition::TopicPartition(_lawspecRecordField0,
// _lawspecRecordField1) in let it = attempt (initProducerIdRequest (Maybe::Present(txid))) in match
// (it) { Either::Left _lawspecSelection0x0 -> false; Either::Right _lawspecSelection0x0 -> let it =
// attempt (initProducerIdRequest (Maybe::Present(txid))) in match (it) { Either::Left
// _match__lawspecSelection0x0_0 -> false; Either::Right _match__lawspecSelection0x0_0 -> ((fencedBy
// _lawspecSelection0x0 _match__lawspecSelection0x0_0 And match (attempt (addPartitionsToTxnRequest
// txid (match (_lawspecSelection0x0) {
// lawtwin.kafka.model::type::ProducerIdAndEpoch::ProducerIdAndEpoch lawspecFieldproducerId
// lawspecFieldproducerEpoch -> lawspecFieldproducerId }) (match (_lawspecSelection0x0) {
// lawtwin.kafka.model::type::ProducerIdAndEpoch::ProducerIdAndEpoch lawspecFieldproducerId
// lawspecFieldproducerEpoch -> lawspecFieldproducerEpoch }) (List::Cons(tp, List::Nil())))) {
// Either::Left lawspecFailure -> let it = lawspecFailure in match (it) {
// lawtwin.kafka.model::type::KafkaError::ProducerFenced -> true;
// lawtwin.kafka.model::type::KafkaError::UnknownTopicOrPartition -> false;
// lawtwin.kafka.model::type::KafkaError::TopicAlreadyExists -> false;
// lawtwin.kafka.model::type::KafkaError::InvalidTopic -> false;
// lawtwin.kafka.model::type::KafkaError::InvalidPartitions -> false;
// lawtwin.kafka.model::type::KafkaError::InvalidRecord -> false;
// lawtwin.kafka.model::type::KafkaError::InvalidRequest -> false;
// lawtwin.kafka.model::type::KafkaError::OffsetOutOfRange -> false;
