    fn check_body(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        batch: ls::Value,
        _with_cluster: ls::Value,
    ) -> ls::Result<()> {
        let condition = ls::called(
            "lawtwin.kafka::created",
            lawspec_definitions::created(ctx, vec![t.clone(), ls::Value::Integer(1i128.into())]),
        )?;
        if condition.boolean()? {
            let actual = ls::called(
                "lawtwin.kafka::transactionThenRead",
                lawspec_definitions::transaction_then_read(
                    ctx,
                    vec![
                        t.clone(),
                        txid.clone(),
                        batch.clone(),
                        ls::Value::Bool(false),
                    ],
                ),
            )?;
            let expected = ls::Value::Bool(true);
            ls::expect_equal(
                &actual,
                &expected,
                "lawtwin.kafka::Broker: |read-committed fetches never see open or aborted transactions| [native] — ../src/contract.lawspec:173",
            )?;
        }
        Ok(())
    }

    fn check(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        batch: ls::Value,
    ) -> ls::Result<()> {
        let t = lawspec_schema::schema()?.validate_with_context(
            t,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let txid = lawspec_schema::schema()?.validate_with_context(
            txid,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let batch = lawspec_schema::schema()?.validate_with_context(
            batch,
            &ls::TypeRef::named(
                "List",
                vec![ls::TypeRef::named(
                    "lawtwin.kafka.model::type::Record",
                    vec![],
                )],
            ),
            64,
            ctx,
        )?;
        let with_cluster = ls::called(
            "lawtwin.kafka::connectCluster",
            connect_cluster(ctx, vec![ls::Value::Unit]),
        )?;
        ls::bracket(
            ctx,
            |ctx| {
                let installing = vec![("lawtwin.kafka::ability::Broker".to_string(), {
                    let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker> =
                        std::sync::Arc::new(adapter::BrokerHandler::new(
                            <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                lawspec_schema::schema()?.native_value_with_context(
                                    with_cluster.clone(),
                                    &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                    64,
                                    ctx,
                                )?,
                            )?,
                        ));
                    ls::installed_native::<adapter::BrokerHandler, _>(handler)
                })];
                ctx.install_handlers(installing);
                check_body(
                    ctx,
                    t.clone(),
                    txid.clone(),
                    batch.clone(),
                    with_cluster.clone(),
                )?;
                Ok(())
            },
            |ctx| {
                Ok(ls::called(
                    "lawtwin.kafka::disconnectCluster",
                    disconnect_cluster(ctx, vec![with_cluster.clone()]),
                )?)
            },
        )?;
        Ok(())
    }

    fn valid(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        batch: ls::Value,
    ) -> ls::Result<bool> {
        let condition = ls::called(
            "lawtwin.kafka::lawtwinKafkaModelValidTopicName",
            lawspec_definitions::lawtwin_kafka_model_valid_topic_name(ctx, vec![t.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::binary("!=", "Text", txid.clone(), ls::Value::Text("".to_owned()))?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::called(
            "lawtwin.kafka::smallBatch",
            lawspec_definitions::small_batch(ctx, vec![batch.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        Ok(true)
    }

