    fn check_body(
        ctx: &mut ls::Context,
        t: ls::Value,
        first: ls::Value,
        second: ls::Value,
        _with_cluster: ls::Value,
    ) -> ls::Result<()> {
        let condition = ls::called(
            "lawtwin.kafka::created",
            lawspec_definitions::created(ctx, vec![t.clone(), ls::Value::Integer(1i128.into())]),
        )?;
        if condition.boolean()? {
            let actual = {
                let a = ls::called(
                    "send",
                    lawspec_abilities::lawtwin_kafka::perform_send(
                        ctx,
                        vec![{
                            let record_field = t.clone();
                            let record_field_2 = ls::construct_data(
                                "lawtwin.kafka::type::PartitionChoice::ToPartition",
                                vec![ls::Value::Integer(0i128.into())],
                            );
                            let record_field_3 = first.clone();
                            ls::construct_data(
                                "lawtwin.kafka::type::ProducerRecord::ProducerRecord",
                                vec![
                                    record_field.clone(),
                                    record_field_2.clone(),
                                    record_field_3.clone(),
                                ],
                            )
                        }],
                    ),
                )?;
                let b = ls::called(
                    "send",
                    lawspec_abilities::lawtwin_kafka::perform_send(
                        ctx,
                        vec![{
                            let record_field = t.clone();
                            let record_field_2 = ls::construct_data(
                                "lawtwin.kafka::type::PartitionChoice::ToPartition",
                                vec![ls::Value::Integer(0i128.into())],
                            );
                            let record_field_3 = second.clone();
                            ls::construct_data(
                                "lawtwin.kafka::type::ProducerRecord::ProducerRecord",
                                vec![
                                    record_field.clone(),
                                    record_field_2.clone(),
                                    record_field_3.clone(),
                                ],
                            )
                        }],
                    ),
                )?;
                ls::called(
                    "lawtwin.kafka::readInOrder",
                    lawspec_definitions::read_in_order(
                        ctx,
                        vec![a.clone(), b.clone(), first.clone(), second.clone()],
                    ),
                )?
            };
            let expected = ls::Value::Bool(true);
            ls::expect_equal(
                &actual,
                &expected,
                "lawtwin.kafka::Producer: |records sent to one partition are read in the order sent| [native] — ../src/contract.lawspec:1142",
            )?;
        }
        Ok(())
    }

    fn check(
        ctx: &mut ls::Context,
        t: ls::Value,
        first: ls::Value,
        second: ls::Value,
    ) -> ls::Result<()> {
        let t = lawspec_schema::schema()?.validate_with_context(
            t,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let first = lawspec_schema::schema()?.validate_with_context(
            first,
            &ls::TypeRef::named("lawtwin.kafka.model::type::Record", vec![]),
            64,
            ctx,
        )?;
        let second = lawspec_schema::schema()?.validate_with_context(
            second,
            &ls::TypeRef::named("lawtwin.kafka.model::type::Record", vec![]),
            64,
            ctx,
        )?;
        let with_cluster = ls::called(
            "lawtwin.kafka::connectCluster",
            connect_cluster(ctx, vec![ls::Value::Unit]),
        )?;
        ls::bracket(
            ctx,
            |ctx| {
                let installing = vec![
                    ("lawtwin.kafka::ability::Producer".to_string(), {
                        let handler: std::sync::Arc<
                            dyn lawspec_abilities::lawtwin_kafka::Producer,
                        > = std::sync::Arc::new(adapter::ProducerHandler::new(
                            <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                lawspec_schema::schema()?.native_value_with_context(
                                    with_cluster.clone(),
                                    &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                    64,
                                    ctx,
                                )?,
                            )?,
                        ));
                        ls::installed_native::<adapter::ProducerHandler, _>(handler)
                    }),
                    ("lawtwin.kafka::ability::Broker".to_string(), {
                        let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker> =
                            std::sync::Arc::new(adapter::BrokerHandler::new(
                                <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                    lawspec_schema::schema()?.native_value_with_context(
                                        with_cluster.clone(),
                                        &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                        64,
                                        ctx,
                                    )?,
                                )?,
                            ));
                        ls::installed_native::<adapter::BrokerHandler, _>(handler)
                    }),
                    ("lawtwin.kafka::ability::Consumer".to_string(), {
                        let handler: std::sync::Arc<
                            dyn lawspec_abilities::lawtwin_kafka::Consumer,
                        > = std::sync::Arc::new(adapter::ConsumerHandler::new(
                            <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                lawspec_schema::schema()?.native_value_with_context(
                                    with_cluster.clone(),
                                    &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                    64,
                                    ctx,
                                )?,
                            )?,
                        ));
                        ls::installed_native::<adapter::ConsumerHandler, _>(handler)
                    }),
                ];
                ctx.install_handlers(installing);
                check_body(
                    ctx,
                    t.clone(),
                    first.clone(),
                    second.clone(),
                    with_cluster.clone(),
                )?;
                Ok(())
            },
            |ctx| {
                Ok(ls::called(
                    "lawtwin.kafka::disconnectCluster",
                    disconnect_cluster(ctx, vec![with_cluster.clone()]),
                )?)
            },
        )?;
        Ok(())
    }

    fn valid(
        ctx: &mut ls::Context,
        t: ls::Value,
        _first: ls::Value,
        _second: ls::Value,
    ) -> ls::Result<bool> {
        let condition = ls::called(
            "lawtwin.kafka::lawtwinKafkaModelValidTopicName",
            lawspec_definitions::lawtwin_kafka_model_valid_topic_name(ctx, vec![t.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        Ok(true)
    }

