// railwayValue1 -> true } And (beginTransaction == Either::Right(unitValue))) And match (attempt
// (initProducerIdRequest (Maybe::Present(txid)))) { Either::Left railwayError0 -> false;
// Either::Right railwayValue1 -> true }) And (sendInTransaction (let _lawspecRecordField0 = t in
// let _lawspecRecordField1 = lawtwin.kafka::type::PartitionChoice::ToPartition(0) in let
// _lawspecRecordField2 = r in
