    fn check_body(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        r: ls::Value,
        _with_cluster: ls::Value,
    ) -> ls::Result<()> {
        let condition = ls::called(
            "lawtwin.kafka::created",
            lawspec_definitions::created(ctx, vec![t.clone(), ls::Value::Integer(1i128.into())]),
        )?;
        if condition.boolean()? {
            let actual = if if if match ls::called(
                "initTransactions",
                lawspec_abilities::lawtwin_kafka::perform_init_transactions(
                    ctx,
                    vec![txid.clone()],
                ),
            )? {
                ls::Value::Left(payload) => {
                    let _railway_error0 = *payload;
                    ls::Value::Bool(false)
                }
                ls::Value::Right(payload) => {
                    let _railway_value1 = *payload;
                    ls::Value::Bool(true)
                }
                _ => return Err("invalid match value".into()),
            }
            .boolean()?
            {
                ls::binary(
                    "==",
                    "Either lawtwin.kafka.model::type::KafkaError Unit",
                    ls::called(
                        "beginTransaction",
                        lawspec_abilities::lawtwin_kafka::perform_begin_transaction(ctx, vec![]),
                    )?,
                    ls::construct("Either::Right", vec![ls::Value::Unit])?,
                )?
            } else {
                ls::Value::Bool(false)
            }
            .boolean()?
            {
                match ls::attempt(
                    ctx,
                    "lawspec::ability::Fail(lawtwin.kafka.model::type::KafkaError)",
                    |ctx: &mut ls::Context| -> ls::Result<ls::Value> {
                        let value = ls::called(
                            "initProducerIdRequest",
                            lawspec_abilities::lawtwin_kafka::perform_init_producer_id_request(
                                ctx,
                                vec![ls::construct("Maybe::Present", vec![txid.clone()])?],
                            ),
                        )?;
                        Ok(value)
                    },
                    |value| ls::construct("Either::Right", vec![value]),
                    |value| ls::construct("Either::Left", vec![value]),
                )? {
                    ls::Value::Left(payload) => {
                        let _railway_error0 = *payload;
                        ls::Value::Bool(false)
                    }
                    ls::Value::Right(payload) => {
                        let _railway_value1 = *payload;
                        ls::Value::Bool(true)
                    }
                    _ => return Err("invalid match value".into()),
                }
            } else {
                ls::Value::Bool(false)
            }
            .boolean()?
            {
                ls::binary(
                    "==",
                    "Either lawtwin.kafka.model::type::KafkaError lawtwin.kafka::type::RecordMetadata",
                    ls::called(
                        "sendInTransaction",
                        lawspec_abilities::lawtwin_kafka::perform_send_in_transaction(
                            ctx,
                            vec![{
                                let record_field = t.clone();
                                let record_field_2 = ls::construct_data(
                                    "lawtwin.kafka::type::PartitionChoice::ToPartition",
                                    vec![ls::Value::Integer(0i128.into())],
                                );
                                let record_field_3 = r.clone();
                                ls::construct_data(
                                    "lawtwin.kafka::type::ProducerRecord::ProducerRecord",
                                    vec![
                                        record_field.clone(),
                                        record_field_2.clone(),
                                        record_field_3.clone(),
                                    ],
                                )
                            }],
                        ),
                    )?,
                    ls::construct(
                        "Either::Left",
                        vec![ls::construct_data(
                            "lawtwin.kafka.model::type::KafkaError::ProducerFenced",
                            vec![],
                        )],
                    )?,
                )?
            } else {
                ls::Value::Bool(false)
            };
            let expected = ls::Value::Bool(true);
            ls::expect_equal(
                &actual,
                &expected,
                "lawtwin.kafka::Transactions: |a newer instance fences a zombie| [native] — ../src/contract.lawspec:1640",
            )?;
        }
        Ok(())
    }

    fn check(ctx: &mut ls::Context, t: ls::Value, txid: ls::Value, r: ls::Value) -> ls::Result<()> {
        let t = lawspec_schema::schema()?.validate_with_context(
            t,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let txid = lawspec_schema::schema()?.validate_with_context(
            txid,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let r = lawspec_schema::schema()?.validate_with_context(
            r,
            &ls::TypeRef::named("lawtwin.kafka.model::type::Record", vec![]),
            64,
            ctx,
        )?;
        let with_cluster = ls::called(
            "lawtwin.kafka::connectCluster",
            connect_cluster(ctx, vec![ls::Value::Unit]),
        )?;
        ls::bracket(
            ctx,
            |ctx| {
                let installing = vec![
                    ("lawtwin.kafka::ability::Transactions".to_string(), {
                        let handler: std::sync::Arc<
                            dyn lawspec_abilities::lawtwin_kafka::Transactions,
                        > = std::sync::Arc::new(adapter::TransactionsHandler::new(
                            <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                lawspec_schema::schema()?.native_value_with_context(
                                    with_cluster.clone(),
                                    &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                    64,
                                    ctx,
                                )?,
                            )?,
                        ));
                        ls::installed_native::<adapter::TransactionsHandler, _>(handler)
                    }),
                    ("lawtwin.kafka::ability::Broker".to_string(), {
                        let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker> =
                            std::sync::Arc::new(adapter::BrokerHandler::new(
                                <crate::lawspec_data::Cluster as ls::FromValue>::from_value(
                                    lawspec_schema::schema()?.native_value_with_context(
                                        with_cluster.clone(),
                                        &ls::TypeRef::named("lawtwin.kafka::type::Cluster", vec![]),
                                        64,
                                        ctx,
                                    )?,
                                )?,
                            ));
                        ls::installed_native::<adapter::BrokerHandler, _>(handler)
                    }),
                ];
                ctx.install_handlers(installing);
                check_body(
                    ctx,
                    t.clone(),
                    txid.clone(),
                    r.clone(),
                    with_cluster.clone(),
                )?;
                Ok(())
            },
            |ctx| {
                Ok(ls::called(
                    "lawtwin.kafka::disconnectCluster",
                    disconnect_cluster(ctx, vec![with_cluster.clone()]),
                )?)
            },
        )?;
        Ok(())
    }

    fn valid(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        _r: ls::Value,
    ) -> ls::Result<bool> {
        let condition = ls::called(
            "lawtwin.kafka::lawtwinKafkaModelValidTopicName",
            lawspec_definitions::lawtwin_kafka_model_valid_topic_name(ctx, vec![t.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::binary("!=", "Text", txid.clone(), ls::Value::Text("".to_owned()))?;
        if !condition.boolean()? {
            return Ok(false);
        }
        Ok(true)
    }

