// lawtwin.kafka.model::type::TopicPartition::TopicPartition(_lawspecRecordField0,
// _lawspecRecordField1) in let before = offsetFetchRequest g tp in ((((match (initTransactions
// txid) { Either::Left railwayError0 -> false; Either::Right railwayValue1 -> true } And
// (beginTransaction == Either::Right(unitValue))) And (sendOffsetsToTransaction g (List::Cons(let
// _lawspecRecordField0 = tp in let _lawspecRecordField1 = offset in
// lawtwin.kafka.model::type::OffsetEntry::OffsetEntry(_lawspecRecordField0, _lawspecRecordField1),
// List::Nil())) == Either::Right(unitValue))) And (abortTransaction == Either::Right(unitValue)))
// And (offsetFetchRequest g tp == before)) = true end for all
