    fn check_body(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        aborted: ls::Value,
        plain: ls::Value,
    ) -> ls::Result<()> {
        let condition = ls::called(
            "lawtwin.kafka::created",
            lawspec_definitions::created(ctx, vec![t.clone(), ls::Value::Integer(1i128.into())]),
        )?;
        if condition.boolean()? {
            let actual = {
                let tp = {
                    let record_field = t.clone();
                    let record_field_2 = ls::Value::Integer(0i128.into());
                    ls::construct_data(
                        "lawtwin.kafka.model::type::TopicPartition::TopicPartition",
                        vec![record_field.clone(), record_field_2.clone()],
                    )
                };
                let a = ls::called(
                    "lawtwin.kafka::writeAborted",
                    lawspec_definitions::write_aborted(
                        ctx,
                        vec![tp.clone(), txid.clone(), aborted.clone()],
                    ),
                )?;
                let p = ls::attempt(
                    ctx,
                    "lawspec::ability::Fail(lawtwin.kafka.model::type::KafkaError)",
                    |ctx: &mut ls::Context| -> ls::Result<ls::Value> {
                        let value = ls::called(
                            "produceRequest",
                            lawspec_abilities::lawtwin_kafka::perform_produce_request(
                                ctx,
                                vec![
                                    tp.clone(),
                                    ls::construct("Maybe::Absent", vec![])?,
                                    ls::construct(
                                        "List::Cons",
                                        vec![plain.clone(), ls::construct("List::Nil", vec![])?],
                                    )?,
                                ],
                            ),
                        )?;
                        Ok(value)
                    },
                    |value| ls::construct("Either::Right", vec![value]),
                    |value| ls::construct("Either::Left", vec![value]),
                )?;
                let _ignored = ls::called(
                    "setIsolationLevel",
                    lawspec_abilities::lawtwin_kafka::perform_set_isolation_level(
                        ctx,
                        vec![ls::construct_data(
                            "lawtwin.kafka.model::type::IsolationLevel::ReadCommitted",
                            vec![],
                        )],
                    ),
                )?;
                let _ignored_2 = ls::called(
                    "assign",
                    lawspec_abilities::lawtwin_kafka::perform_assign(
                        ctx,
                        vec![ls::construct(
                            "List::Cons",
                            vec![tp.clone(), ls::construct("List::Nil", vec![])?],
                        )?],
                    ),
                )?;
                let it = ls::called(
                    "poll",
                    lawspec_abilities::lawtwin_kafka::perform_poll(
                        ctx,
                        vec![ls::Value::Integer(100i128.into())],
                    ),
                )?;
                match it.clone() {
                    ls::Value::Left(payload) => {
                        let _selection = *payload;
                        ls::Value::Bool(false)
                    }
                    ls::Value::Right(payload) => {
                        let selection = *payload;
                        let left = {
                            let it_2 = a.clone();
                            match it_2.clone() {
                                ls::Value::Maybe(Some(payload)) => {
                                    let match_selection = *payload;
                                    let value = {
                                        let argument_1 = match_selection.clone();
                                        let argument_2 = {
                                            let argument_1 = ls::called(
                                                "lawtwin.kafka::receivedOffsets",
                                                lawspec_definitions::received_offsets(
                                                    ctx,
                                                    vec![selection.clone()],
                                                ),
                                            )?;
                                            ls::called(
                                                "lawtwin.kafka::lawspec_lawspecCollectionsSetOf_b5406356c975f29bf9190306bcb4889d24f84b6b0bc2ee4d7355a65e0a2ed1f9ae3ce5c28787",
                                                lawspec_definitions::lawspec_collections_set_of_list_int64(
                                                    ctx,
                                                    vec![argument_1],
                                                ),
                                            )?
                                        };
                                        ls::called(
                                            "lawtwin.kafka::lawspec_lawspecCollectionsSetMember_b5328d10ee86ebc0c44319820223379219007d41bad7be90e09a47775568f4b03f4aa46490fd",
                                            lawspec_definitions::lawspec_collections_set_member_int64_set_int64(
                                                ctx,
                                                vec![argument_1, argument_2],
                                            ),
                                        )?
                                    };
                                    ls::Value::Bool(!value.boolean()?)
                                }
                                ls::Value::Maybe(None) => ls::Value::Bool(false),
                                _ => return Err("invalid match value".into()),
                            }
                        };
                        if left.boolean()? {
                            let it_2 = p.clone();
                            match it_2.clone() {
                                ls::Value::Right(payload) => {
                                    let match_selection = *payload;
                                    let argument_1 = match_selection.clone();
                                    let argument_2 = {
                                        let argument_1 = ls::called(
                                            "lawtwin.kafka::receivedOffsets",
                                            lawspec_definitions::received_offsets(
                                                ctx,
                                                vec![selection.clone()],
                                            ),
                                        )?;
                                        ls::called(
                                            "lawtwin.kafka::lawspec_lawspecCollectionsSetOf_b5406356c975f29bf9190306bcb4889d24f84b6b0bc2ee4d7355a65e0a2ed1f9ae3ce5c28787",
                                            lawspec_definitions::lawspec_collections_set_of_list_int64(
                                                ctx,
                                                vec![argument_1],
                                            ),
                                        )?
                                    };
                                    ls::called(
                                        "lawtwin.kafka::lawspec_lawspecCollectionsSetMember_b5328d10ee86ebc0c44319820223379219007d41bad7be90e09a47775568f4b03f4aa46490fd",
                                        lawspec_definitions::lawspec_collections_set_member_int64_set_int64(
                                            ctx,
                                            vec![argument_1, argument_2],
                                        ),
                                    )?
                                }
                                ls::Value::Left(payload) => {
                                    let _match_selection = *payload;
                                    ls::Value::Bool(false)
                                }
                                _ => return Err("invalid match value".into()),
                            }
                        } else {
                            ls::Value::Bool(false)
                        }
                    }
                    _ => return Err("invalid match value".into()),
                }
            };
            let expected = ls::Value::Bool(true);
            ls::expect_equal(
                &actual,
                &expected,
                "lawtwin.kafka::Consumer: |a read-committed consumer never sees aborted records| [reference] — ../src/contract.lawspec:1353",
            )?;
        }
        Ok(())
    }

    fn check(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        aborted: ls::Value,
        plain: ls::Value,
    ) -> ls::Result<()> {
        let shared_cluster =
            std::sync::Arc::new(lawspec_abilities::lawtwin_kafka::Cluster::new(ctx));
        let installing = vec![
            ("lawtwin.kafka::ability::Consumer".to_string(), {
                let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Consumer> =
                    std::sync::Arc::new(lawspec_abilities::lawtwin_kafka::KafkaConsumer::new(ctx));
                ls::installed(handler)
            }),
            ("lawtwin.kafka::ability::Broker".to_string(), {
                let handler: std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker> =
                    shared_cluster.clone();
                ls::installed(handler)
            }),
        ];
        ctx.install_handlers(installing);
        let t = lawspec_schema::schema()?.validate_with_context(
            t,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let txid = lawspec_schema::schema()?.validate_with_context(
            txid,
            &ls::TypeRef::named("Text", vec![]),
            64,
            ctx,
        )?;
        let aborted = lawspec_schema::schema()?.validate_with_context(
            aborted,
            &ls::TypeRef::named("lawtwin.kafka.model::type::Record", vec![]),
            64,
            ctx,
        )?;
        let plain = lawspec_schema::schema()?.validate_with_context(
            plain,
            &ls::TypeRef::named("lawtwin.kafka.model::type::Record", vec![]),
            64,
            ctx,
        )?;
        check_body(ctx, t.clone(), txid.clone(), aborted.clone(), plain.clone())?;
        Ok(())
    }

    fn valid(
        ctx: &mut ls::Context,
        t: ls::Value,
        txid: ls::Value,
        _aborted: ls::Value,
        _plain: ls::Value,
    ) -> ls::Result<bool> {
        let condition = ls::called(
            "lawtwin.kafka::lawtwinKafkaModelValidTopicName",
            lawspec_definitions::lawtwin_kafka_model_valid_topic_name(ctx, vec![t.clone()]),
        )?;
        if !condition.boolean()? {
            return Ok(false);
        }
        let condition = ls::binary("!=", "Text", txid.clone(), ls::Value::Text("".to_owned()))?;
        if !condition.boolean()? {
            return Ok(false);
        }
        Ok(true)
    }

    #[test]
    fn boundaries() -> ls::Result<()> {
        ls::with_stack(|| {
            ls::finite_cases(
                &ls::FiniteCover::Branches(vec![
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("o".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text(" ".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_6(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_6(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("t".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("Hello, World!".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_9(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_9(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| {
                            Ok(ls::Value::Text("7oIEcKM".to_owned()))
                        }]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("λ日本語😀".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_11(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_11(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| {
                            Ok(ls::Value::Text("ucnH_8".to_owned()))
                        }]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("a\n\t\"\\$\0z".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_13(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_13(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("-".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("é".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_16(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_16(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                    (
                        ls::FiniteDomain::Values(vec![|_ctx| Ok(ls::Value::Text("t".to_owned()))]),
                        ls::FiniteCover::Branches(vec![(
                            ls::FiniteDomain::Values(vec![|_ctx| {
                                Ok(ls::Value::Text("\0aλ😀\u{10ffff}".to_owned()))
                            }]),
                            ls::FiniteCover::Branches(vec![(
                                ls::FiniteDomain::Values(vec![|ctx| Ok(literal_11(ctx)?)]),
                                ls::FiniteCover::Branches(vec![(
                                    ls::FiniteDomain::Values(vec![|ctx| Ok(literal_11(ctx)?)]),
                                    ls::FiniteCover::Copies(1),
                                )]),
                            )]),
                        )]),
                    ),
                ]),
                |case_index, factories| {
                    let ctx = &mut ls::Context::testing();
                    let values = factories
                        .iter()
                        .map(|factory| factory.materialize(ctx))
                        .collect::<ls::Result<Vec<_>>>()?;
                    check(
                        ctx,
                        values[0].clone(),
                        values[1].clone(),
                        values[2].clone(),
                        values[3].clone(),
                    )
                    .map_err(|error| {
                        format!("boundary {}: values={values:?}: {error}", case_index + 1)
                    })
                },
            )?;
            Ok(())
        })
    }

